from collections import defaultdict
def solve(inp):
    H,W=len(inp),len(inp[0])
    cnt=defaultdict(int)
    for r in range(H):
        for c in range(W): cnt[inp[r][c]]+=1
    order=sorted(cnt,key=lambda x:-cnt[x]); bg=order[0]
    line=[x for x in order[1:] if cnt[x]>W//2 or cnt[x]>H//2]
    line=line[0] if line else None
    if line is None:
        # second most common
        line=order[1]
    seps_r=[r for r in range(H) if sum(inp[r][c]==line for c in range(W))>W*0.7]
    seps_c=[c for c in range(W) if sum(inp[r][c]==line for r in range(H))>H*0.7]
    anom=defaultdict(list)
    for r in seps_r:
        for c in range(W):
            if inp[r][c]!=line: anom[inp[r][c]].append((r,c))
    for c in seps_c:
        for r in range(H):
            if inp[r][c]!=line and (r not in seps_r or True): 
                pass
    # also anomalies on vertical lines within non-sep rows
    for c in seps_c:
        for r in range(H):
            if r not in seps_r and inp[r][c]!=line: anom[inp[r][c]].append((r,c))
    rows=sorted({r for p in anom.values() for r,_ in p})
    cols=sorted({c for _,c in []}|{c for p in anom.values() for _,c in p})
    rg=[(rows[i],rows[i+1]) for i in range(len(rows)-1)]
    cg=[(cols[i],cols[i+1]) for i in range(len(cols)-1)]
    out=[[bg]*(len(cg)) for _ in range(len(rg))]
    for v,p in anom.items():
        if v==line: continue
        Ri=[i for i,(a,b) in enumerate(rg) if a in [r for r,_ in p] and b in [r for r,_ in p]]
        Ci=[i for i,(a,b) in enumerate(cg) if a in [c for _,c in p] and b in [c for _,c in p]]
        for i in Ri:
            for j in Ci:
                if out[i][j]!=bg and out[i][j]!=v: pass
        # fill only if all four corners of gap equal v
        for i in Ri:
            for j in Ci:
                r1,r2=rg[i]; c1,c2=cg[j]
                if inp[r1][c1]==inp[r1][c2]==inp[r2][c1]==inp[r2][c2]==v:
                    out[i][j]=v
    return out
